// Parse OpenAI-compatible chat completion response
// Expected shape: { choices: [{ message: { content: "<json string>" } }] }
// content is a JSON string like {"message_type":"...","question_type":"...","concepts_mentioned":[...]}

const results = [];

for (const item of $input.all()) {
  const stored = $('Restore message data').item.json;
  let parsed = {};

  try {
    const content = item.json?.choices?.[0]?.message?.content || item.json?.message?.content || '{}';
    parsed = typeof content === 'string' ? JSON.parse(content) : content;
  } catch (e) {
    // Fallback — keep going even if the LLM returned malformed JSON
    parsed = { message_type: 'other', question_type: 'none', concepts_mentioned: [] };
  }

  results.push({
    json: {
      ...stored,
      message_type:       parsed.message_type       || 'other',
      question_type:      parsed.question_type      || 'none',
      concepts_mentioned: Array.isArray(parsed.concepts_mentioned) ? parsed.concepts_mentioned : []
    }
  });
}

return results;

// Embedding via OpenAI-compatible API (provider-agnostic)
// Reads endpoint/model/key from n8n env vars (set via docker-compose).

const baseUrl = $env.EMBEDDING_BASE_URL || 'https://api.openai.com/v1';
const model   = $env.EMBEDDING_MODEL    || 'text-embedding-3-small';
const apiKey  = $env.EMBEDDING_API_KEY  || '';

const results = [];

for (const item of $input.all()) {
  const text = (item.json.text || '').slice(0, 8000);

  const response = await this.helpers.httpRequest({
    method: 'POST',
    url:    baseUrl + '/embeddings',
    headers: {
      'Content-Type':  'application/json',
      'Authorization': 'Bearer ' + apiKey
    },
    body: { model, input: text },
    json: true
  });

  const vector = response?.data?.[0]?.embedding;
  if (!vector) {
    throw new Error('No embedding returned from ' + baseUrl);
  }

  results.push({ json: { ...item.json, embedding: vector } });
}

return results;

// Stores the cursor. Same two fixes as "Read lastTimestamp", plus one more:
// PATCH on an object that does not exist is a 404, so the very first run
// could never have written a cursor. Create it, then patch from then on.
const base = `http://smartrag-weaviate:${$env.WEAVIATE_HTTP_PORT || 8080}`;
const id = '3fa2478e-a528-4ca4-84e4-50bc76948667';
const headers = {
  'Authorization': `Bearer ${$env.WEAVIATE_API_KEY}`,
  'Content-Type': 'application/json'
};
const newTimestamp = new Date().toISOString();

try {
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${base}/v1/objects/WorkflowState/${id}`,
    headers,
    body: { properties: { key: 'lastTimestamp', value: newTimestamp } },
    json: true
  });
} catch (e) {
  const status = e?.httpCode || e?.statusCode || e?.response?.status;
  if (String(status) !== '404') {
    throw e;
  }
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${base}/v1/objects`,
    headers,
    body: {
      class: 'WorkflowState',
      id,
      properties: { key: 'lastTimestamp', value: newTimestamp }
    },
    json: true
  });
}

return [{ json: { updated: true, newTimestamp } }];
